import sys
from math import gcd

def main():
    n, m = map(int, sys.stdin.read().split())
    if m < n - 1:
        print("Impossible")
        return
    if m > n * (n - 1) // 2:
        print("Impossible")
        return

    print("Possible")
    edges = []
    for i in range(2, n + 1):
        if gcd(i, i - 1) == 1:
            edges.append((i - 1, i))
        else:
            edges.append((1, i))
    extra_edges = m - (n - 1)
    current = 2
    while extra_edges > 0:
        if current >= n:
            current = 2
        for i in range(1, n + 1):
            if i != current and gcd(current, i) == 1 and (current, i) not in edges and (i, current) not in edges:
                edges.append((current, i))
                extra_edges -= 1
                if extra_edges == 0:
                    break
        current += 1

    for edge in edges:
        print(edge[0], edge[1])

main()
